function exactCalendarAge(birth,asOf){let years=asOf.getFullYear()-birth.getFullYear(),anniversary=new Date(birth);anniversary.setFullYear(birth.getFullYear()+years);if(anniversary>asOf){years--;anniversary=new Date(birth);anniversary.setFullYear(birth.getFullYear()+years)}let months=0,cursor=new Date(anniversary);while(months<11){const next=new Date(cursor);next.setMonth(next.getMonth()+1);if(next>asOf)break;cursor=next;months++}const remainingDays=Math.floor((asOf-cursor)/86400000),totalDays=Math.floor((asOf-birth)/86400000);return{years,months,days:remainingDays,totalDays}}
